#include <iostream>
#include <type_traits>
#include <conditional>
template <typename T, bool condition>
struct conditional_type {
  using type = std::conditional_t<condition, T, void>;
};

template <typename T>
using select_type = typename conditional_type<T, std::is_integral_v<T>>::type;

template <typename T>
void process(T value) {
  if constexpr (std::is_integral_v<T>) {
    std::cout << "Integral: " << value << std::endl;
  } else {
    std::cout << "Not Integral" << std::endl; 
  }
}
int main() {
  process(5);       // Compile-time branch selection for integral type
  process(5.5);     // Compile-time branch selection for floating-point type
  select_type<int> i; // i is an int
  //select_type<double> d; // Compilation error due to void
  return 0;
}
